import{_ as e,o,c as i,a2 as l}from"./chunks/framework.BjkiRu3Q.js";const _=JSON.parse('{"title":"Σχεδιασμός, γλώσσες και SEO","description":"","frontmatter":{},"headers":[],"relativePath":"el/websites/design-and-localization.md","filePath":"el/websites/design-and-localization.md"}'),t={name:"el/websites/design-and-localization.md"};function r(s,a,n,d,c,h){return o(),i("div",null,[...a[0]||(a[0]=[l('<h1 id="σχεδιασμος-γλωσσες-και-seo" tabindex="-1">Σχεδιασμός, γλώσσες και SEO <a class="header-anchor" href="#σχεδιασμος-γλωσσες-και-seo" aria-label="Permalink to &quot;Σχεδιασμός, γλώσσες και SEO&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς — προσχέδιο βάσει κώδικα</p><p>TransferBook+ v0.7.9. Η διαθεσιμότητα εξαρτάται από την εγκατεστημένη έκδοση, τα δικαιώματα και τις ρυθμίσεις. Ο οδηγός δεν επιβεβαιώνει δημόσια δημοσίευση.</p></div><h2 id="σκοπος" tabindex="-1">Σκοπός <a class="header-anchor" href="#σκοπος" aria-label="Permalink to &quot;Σκοπός&quot;">​</a></h2><p>Διαχειριστείτε την οπτική ταυτότητα ανεξάρτητα από το περιεχόμενο των σελίδων. Χρησιμοποιήστε εγκεκριμένα αρχεία και εξουσιοδοτημένο προσχέδιο.</p><h2 id="σχεδιασμος-και-περιεχομενο" tabindex="-1">Σχεδιασμός και περιεχόμενο <a class="header-anchor" href="#σχεδιασμος-και-περιεχομενο" aria-label="Permalink to &quot;Σχεδιασμός και περιεχόμενο&quot;">​</a></h2><ol><li>Στο Design ελέγξτε παλέτα, τυπογραφία, αποστάσεις, στρογγυλοποίηση και κουμπιά.</li><li>Επιλέξτε εγκεκριμένες τοπικές εικόνες. Αποφύγετε αυθαίρετο HTML, scripts ή εξωτερικά URL αρχείων στα πακέτα.</li><li>Επεξεργαστείτε το απλό μεταφρασμένο κείμενο στο πάνελ ενότητας. Υποστηρίζονται Αγγλικά, Ελληνικά, Ιταλικά, Γαλλικά, Γερμανικά και Ισπανικά (<code>en</code>, <code>el</code>, <code>it</code>, <code>fr</code>, <code>de</code>, <code>es</code>).</li><li>Στο Page &amp; SEO ελέγξτε τα μεταδεδομένα ανά γλώσσα χωρίς μη τεκμηριωμένους εμπορικούς ισχυρισμούς.</li><li>Ελέγξτε αντίθεση και αναγνωσιμότητα. Για συνηθισμένο κείμενο ο στόχος WCAG AA είναι τουλάχιστον 4,5:1, εκτός όπου ισχύει σχετική εξαίρεση.</li></ol><h2 id="αναμενομενο-αποτελεσμα" tabindex="-1">Αναμενόμενο αποτέλεσμα <a class="header-anchor" href="#αναμενομενο-αποτελεσμα" aria-label="Permalink to &quot;Αναμενόμενο αποτέλεσμα&quot;">​</a></h2><p>Το σύστημα σχεδιασμού μπορεί να αλλάξει ανεξάρτητα από τις σελίδες και το μεταφρασμένο περιεχόμενο. Ο έλεγχος μεταδεδομένων ή αντίθεσης δεν εγγυάται ευρετηρίαση ή πλήρη προσβασιμότητα.</p><h2 id="αντιμετωπιση-προβληματων" tabindex="-1">Αντιμετώπιση προβλημάτων <a class="header-anchor" href="#αντιμετωπιση-προβληματων" aria-label="Permalink to &quot;Αντιμετώπιση προβλημάτων&quot;">​</a></h2><p>Αν απορριφθεί αρχείο ή γλώσσα, χρησιμοποιήστε υποστηριζόμενες μορφές και εγκεκριμένα στοιχεία. Δείτε <a href="./portable-packages.html">φορητά πακέτα</a>.</p><h2 id="γλωσσικη-καλυψη-στη-v0-7-10" tabindex="-1">Γλωσσική κάλυψη στη v0.7.10 <a class="header-anchor" href="#γλωσσικη-καλυψη-στη-v0-7-10" aria-label="Permalink to &quot;Γλωσσική κάλυψη στη v0.7.10&quot;">​</a></h2><p><strong>Κατάσταση: έκδοση staging ελεγμένη βάσει κώδικα.</strong> Ο έλεγχος <strong>6 Lang</strong> του inspector εμφανίζει μεταφρασμένα, ελλιπή και εφεδρικά πεδία ανά γλώσσα. Η κάλυψη δεν πιστοποιεί την ποιότητα μετάφρασης.</p><ol><li>Εξετάστε την κάλυψη κάθε μίας από τις έξι υποστηριζόμενες γλώσσες.</li><li>Επιλέξτε γλώσσα και χρησιμοποιήστε τις αγγλικές υποδείξεις για έλεγχο. Όπου προσφέρεται, συμπληρώστε κενές τιμές από τα Αγγλικά χωρίς αντικατάσταση υπαρχουσών μεταφράσεων.</li><li>Μεταφράστε το αντιγραμμένο αγγλικό κείμενο και ελέγξτε χειροκίνητα τη διατύπωση, τα μεταδεδομένα, τις ενότητες, τα κουμπιά, την πλοήγηση και το μενού κινητού.</li><li>Αποθηκεύστε και εξαγάγετε το ελεγμένο προσχέδιο. Η εμφάνιση εφεδρικού κειμένου δεν σημαίνει ολοκληρωμένη μετάφραση.</li></ol>',13)])])}const m=e(t,[["render",r]]);export{_ as __pageData,m as default};
